CREATE TABLE IF NOT EXISTS knowledge.war_outpost_rules (
  id text PRIMARY KEY,
  name text NOT NULL,
  outpost_victory_points integer NOT NULL,
  exact_visible_effect text NOT NULL,
  exact_visible_phase_rule text NOT NULL,
  source_id bigint NOT NULL REFERENCES knowledge.sources(source_id),
  review_state text NOT NULL
);
ALTER TABLE knowledge.war_outpost_rules ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON knowledge.war_outpost_rules FROM PUBLIC, anon, authenticated;

